import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第四册：流利英语 · 综合复习与自测 · 第23–33课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第四册：流利英语 · 综合复习与自测 · 第23–33课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-4/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第12–22课","link":"/life/english/new-concept/book-4/review-part-02"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第34–44课","link":"/life/english/new-concept/book-4/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第12–22课","link":"/life/english/new-concept/book-4/review-part-02"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第34–44课","link":"/life/english/new-concept/book-4/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-4/review-part-03.md","filePath":"life/english/new-concept/book-4/review-part-03.md"}'),n={name:"life/english/new-concept/book-4/review-part-03.md"};function r(i,e,l,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-综合复习与自测-·-第23–33课" tabindex="-1">第四册：流利英语 · 综合复习与自测 · 第23–33课 <a class="header-anchor" href="#第四册-流利英语-·-综合复习与自测-·-第23–33课" aria-label="Permalink to &quot;第四册：流利英语 · 综合复习与自测 · 第23–33课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-23-·-现在分词状语与逻辑主语" tabindex="-1">Lesson 23 · 现在分词状语与逻辑主语 <a class="header-anchor" href="#lesson-23-·-现在分词状语与逻辑主语" aria-label="Permalink to &quot;Lesson 23 · 现在分词状语与逻辑主语 {#lesson-23-·-现在分词状语与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Gliding above the field, the bird turned towards the hills.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>示例中谁在 gliding？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the bird</p><p><strong>解析：</strong> 分词状语与主句共享主语。</p></details><p><strong>表达迁移：</strong> 用三句记录一次鸟类观察，含分词状语、动作变化和观察限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Circling above the trees, a large bird gradually gained height. It then moved across the valley without flapping. From the ground, I could not identify the species with confidence.</p><p>动作描述具体，最后将物种判断与观察事实分开。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">回看本课</a></p><h2 id="lesson-24-·-否定或限制副词前置倒装" tabindex="-1">Lesson 24 · 否定或限制副词前置倒装 <a class="header-anchor" href="#lesson-24-·-否定或限制副词前置倒装" aria-label="Permalink to &quot;Lesson 24 · 否定或限制副词前置倒装 {#lesson-24-·-否定或限制副词前置倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>填空：Rarely ___ she choose bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> does</p><p><strong>解析：</strong> 主语 she，现时一般时倒装用 does。</p></details><p><strong>表达迁移：</strong> 选择一件普通物品写三句审美评论，包含一个具体特征和一个观点限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rarely do I notice the shape of an ordinary cup. This one has a narrow base and a softly curved handle. I find the proportions pleasing, although another viewer may prefer a simpler form.</p><p>倒装引入反思，具体特征支撑个人评价，让步句保留不同审美。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">回看本课</a></p><h2 id="lesson-25-·-名词化与施事信息" tabindex="-1">Lesson 25 · 名词化与施事信息 <a class="header-anchor" href="#lesson-25-·-名词化与施事信息" aria-label="Permalink to &quot;Lesson 25 · 名词化与施事信息 {#lesson-25-·-名词化与施事信息}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A reduction in background noise coincided with fewer interruptions during the task.</p><h3 id="练习-1-24" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-24" aria-label="Permalink to &quot;练习 1 {#练习-1-24}&quot;">​</a></h3><p>填空：exposure ___ background noise。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> exposure to 为常见搭配。</p></details><p><strong>表达迁移：</strong> 写三句虚构办公观察，记录噪声变化、任务表现和一个替代解释。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A reduction in corridor noise coincided with fewer interruptions. Staff completed the sorting task more quickly. A change in the task instructions may also have contributed.</p><p>名词化方便总结，但最后一句保留其他解释，避免过度推断。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">回看本课</a></p><h2 id="lesson-26-·-完成式分词状语" tabindex="-1">Lesson 26 · 完成式分词状语 <a class="header-anchor" href="#lesson-26-·-完成式分词状语" aria-label="Permalink to &quot;Lesson 26 · 完成式分词状语 {#lesson-26-·-完成式分词状语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Having compared the layers, the researchers proposed a tentative sequence of events.</p><h3 id="练习-1-25" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-25" aria-label="Permalink to &quot;练习 1 {#练习-1-25}&quot;">​</a></h3><p>示例中比较与提出哪个在先？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 比较在先。</p><p><strong>解析：</strong> having compared 标记先完成的动作。</p></details><p><strong>表达迁移：</strong> 用三句汇报虚构岩层比较，包含前置完成动作、初步结论和保存局限。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Having compared the samples, we placed layer B below layer A in our working sequence. This interpretation remains provisional. Some evidence may have been lost through erosion.</p><p>完成式交代研究顺序，后两句说明暂定性和证据缺失来源。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">回看本课</a></p><h2 id="lesson-27-·-第三条件句与过去反事实" tabindex="-1">Lesson 27 · 第三条件句与过去反事实 <a class="header-anchor" href="#lesson-27-·-第三条件句与过去反事实" aria-label="Permalink to &quot;Lesson 27 · 第三条件句与过去反事实 {#lesson-27-·-第三条件句与过去反事实}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the model had been tested earlier, the designers might have noticed the imbalance.</p><h3 id="练习-1-26" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-26" aria-label="Permalink to &quot;练习 1 {#练习-1-26}&quot;">​</a></h3><p>示例是否声称模型确实更早接受测试？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 它构造过去反事实条件。</p></details><p><strong>表达迁移：</strong> 写三句虚构船模事故复盘：事实、反事实假设、今天的改进。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The model tilted during its first public demonstration. If we had tested it with a full load, we might have detected the imbalance. Future checks should include several loading conditions.</p><p>事实与假设不混写，末句将反思转成明确可测试的改进。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">回看本课</a></p><h2 id="lesson-28-·-间接问句与疑问语序" tabindex="-1">Lesson 28 · 间接问句与疑问语序 <a class="header-anchor" href="#lesson-28-·-间接问句与疑问语序" aria-label="Permalink to &quot;Lesson 28 · 间接问句与疑问语序 {#lesson-28-·-间接问句与疑问语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Could you explain what this term means in plain language?</p><h3 id="练习-1-27" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-27" aria-label="Permalink to &quot;练习 1 {#练习-1-27}&quot;">​</a></h3><p>把 When does the appointment begin? 放入 Could you tell me…?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Could you tell me when the appointment begins?</p><p><strong>解析：</strong> 间接问句使用陈述语序，begins 随单数主语。</p></details><p><strong>表达迁移：</strong> 写三句就诊沟通练习，仅询问信息表达：术语含义、理解核对、书面说明。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Could you explain what this term means? I want to make sure I have understood your explanation correctly. Would it be possible to have the main points in writing?</p><p>问题集中在沟通与理解，使用礼貌框架，不替专业人员提供诊疗结论。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">回看本课</a></p><h2 id="lesson-29-·-使役与许可结构" tabindex="-1">Lesson 29 · 使役与许可结构 <a class="header-anchor" href="#lesson-29-·-使役与许可结构" aria-label="Permalink to &quot;Lesson 29 · 使役与许可结构 {#lesson-29-·-使役与许可结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The air cushion allows the model to move across the smooth floor.</p><h3 id="练习-1-28" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-28" aria-label="Permalink to &quot;练习 1 {#练习-1-28}&quot;">​</a></h3><p>填空：The guide enabled visitors ___ understand the diagram.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> enable + 宾语 + to do。</p></details><p><strong>表达迁移：</strong> 用三句向中学生解释一个纸模型，说明条件、动作和演示边界。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A thin layer of air allows the model to slide over the table. A small fan provides the airflow. This demonstration illustrates one principle rather than the full design of a real craft.</p><p>功能结构清晰，最后一句说明模型只展示部分原理，避免过度类比。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">回看本课</a></p><h2 id="lesson-30-·-介词-which-的关系从句" tabindex="-1">Lesson 30 · 介词 + which 的关系从句 <a class="header-anchor" href="#lesson-30-·-介词-which-的关系从句" aria-label="Permalink to &quot;Lesson 30 · 介词 + which 的关系从句 {#lesson-30-·-介词-which-的关系从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The pressure under which the sensor operates must be recorded.</p><h3 id="练习-1-29" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-29" aria-label="Permalink to &quot;练习 1 {#练习-1-29}&quot;">​</a></h3><p>填空：the depth ___ which the camera was tested。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 在某深度使用 at a depth。</p></details><p><strong>表达迁移：</strong> 用三句介绍一张虚构海底图：测量条件、图像所示、尚未确定的细节。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The report lists the depth at which each image was taken. A ridge appears along the eastern edge. Smaller features remain uncertain because the resolution is limited.</p><p>条件、图形观察和分辨率限制分开表达，不把图像当作无误的直接观看。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">回看本课</a></p><h2 id="lesson-31-·-独立主格的主语与分词" tabindex="-1">Lesson 31 · 独立主格的主语与分词 <a class="header-anchor" href="#lesson-31-·-独立主格的主语与分词" aria-label="Permalink to &quot;Lesson 31 · 独立主格的主语与分词 {#lesson-31-·-独立主格的主语与分词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The clay still damp, the sculptor covered the model before leaving.</p><h3 id="练习-1-30" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-30" aria-label="Permalink to &quot;练习 1 {#练习-1-30}&quot;">​</a></h3><p>示例背景结构的逻辑主语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the clay</p><p><strong>解析：</strong> damp 描述 clay，而不是 sculptor。</p></details><p><strong>表达迁移：</strong> 写三句工作室观察：材料状态、创作者动作、你对形式的个人感受。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The surface still rough, the artist examined the model from the side. She removed a small piece near the base. To me, the new shape seemed lighter and more balanced.</p><p>独立主格提供材料背景，末句 To me 将观众感受与作者意图区分。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">回看本课</a></p><h2 id="lesson-32-·-形容词前置的-as-让步结构" tabindex="-1">Lesson 32 · 形容词前置的 as 让步结构 <a class="header-anchor" href="#lesson-32-·-形容词前置的-as-让步结构" aria-label="Permalink to &quot;Lesson 32 · 形容词前置的 as 让步结构 {#lesson-32-·-形容词前置的-as-让步结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Limited as the evidence is, it gives us a reason to repeat the experiment.</p><h3 id="练习-1-31" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-31" aria-label="Permalink to &quot;练习 1 {#练习-1-31}&quot;">​</a></h3><p>用 although 改写 Limited as the evidence is。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Although the evidence is limited</p><p><strong>解析：</strong> 两者都表达让步。</p></details><p><strong>表达迁移：</strong> 为一位科学家的历史传记写三句评议：让步、旧说的限制、查证方式。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Familiar as the story is, its details still need checking. A later retelling may have simplified the scientist’s methods. We should compare the account with documents from the same period.</p><p>让步不等于接受传说，后两句从叙事简化转向同期材料查证，呼应科学史解释的修正。</p></details><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">回看本课</a></p><h2 id="lesson-33-·-平行结构与-not-only-but-also" tabindex="-1">Lesson 33 · 平行结构与 not only…but also <a class="header-anchor" href="#lesson-33-·-平行结构与-not-only-but-also" aria-label="Permalink to &quot;Lesson 33 · 平行结构与 not only…but also {#lesson-33-·-平行结构与-not-only-but-also}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The course teaches students to question claims, compare sources and explain their conclusions.</p><h3 id="练习-1-32" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-32" aria-label="Permalink to &quot;练习 1 {#练习-1-32}&quot;">​</a></h3><p>改正：Students learn to observe, recording and to explain.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Students learn to observe, record and explain.</p><p><strong>解析：</strong> 三个并列动词共享 to。</p></details><p><strong>表达迁移：</strong> 为一个研究课设计三句学习目标，包含平行动词和一种评估方法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Students will learn to ask questions, compare evidence and defend a conclusion. They will work with two short reports on the same issue. A final discussion will show how clearly they can explain their reasoning.</p><p>目标、材料与评估对应，平行结构使三个能力要求清晰可比。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">回看本课</a></p>',92)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
